CREATE OR REPLACE MODEL `ent-kixavvik-dev.disruptions.togvarsel_lr_am_0630_A`
OPTIONS(model_type='LOGISTIC_REG', l2_reg=0.5, max_iterations=50, data_split_method='NO_SPLIT', input_label_cols=['label']) AS
SELECT et_t5_0630, et_cx_0630, et_cxj_0630, et_md_0630, prev_eve_t5, prev_eve_cancel, prev_pm_t5, sx_inn_0630, sx_infra_0630, sx_amj_0630, sx_amj_inn_0630, sx_mt_0630, sx_big_0630, sx_n_0630, CAST(dow AS STRING) dow_s, low_season, am_bad AS label FROM `ent-kixavvik-dev.disruptions.togvarsel_features` WHERE weekday AND NOT holiday AND am_n > 300 AND pm_n > 300 AND d < '2026-04-01';
CREATE OR REPLACE TABLE `ent-kixavvik-dev.disruptions.togvarsel_pred_lr_am_0630_A` AS
SELECT d, label, predicted_label_probs[OFFSET(0)].prob AS p_raw, (SELECT p.prob FROM UNNEST(predicted_label_probs) p WHERE p.label = TRUE) AS p
FROM ML.PREDICT(MODEL `ent-kixavvik-dev.disruptions.togvarsel_lr_am_0630_A`, (SELECT d, et_t5_0630, et_cx_0630, et_cxj_0630, et_md_0630, prev_eve_t5, prev_eve_cancel, prev_pm_t5, sx_inn_0630, sx_infra_0630, sx_amj_0630, sx_amj_inn_0630, sx_mt_0630, sx_big_0630, sx_n_0630, CAST(dow AS STRING) dow_s, low_season, am_bad AS label FROM `ent-kixavvik-dev.disruptions.togvarsel_features` WHERE weekday AND NOT holiday AND am_n > 300 AND pm_n > 300 AND d >= '2026-04-01'));
